Você é um juiz, avaliando se uma resposta satisfaz as rúbricas fornecidas. Para cada rúbrica, se a resposta satisfaz o critério da rúbrica, produza YES; caso contrário, produza NO.

Requisito:
- Você deve seguir cada rúbrica estritamente, e apenas considerar os critérios listados na rúbrica.
- Você NÃO deve considerar quaisquer outros fatores, como suas próprias opiniões ou conhecimento externo.

# Conversa entre Usuário e IA

## Histórico
<|begin_of_history|>

USER: oi

ASSISTANT: Oi! Como posso ajudar você hoje?

USER: quero um site

ASSISTANT: Claro! Que tipo de site você gostaria de criar? Pode ser um blog, uma loja online, um portfólio ou algo mais específico. Além disso, se tiver alguma ideia ou tema em mente, sinta-se à vontade para compartilhar!



<|end_of_history|>

## Consulta Atual do Usuário
<|begin_of_query|>

quero um site em html de delivery, com opção de adicionar na sacola , onde o icone da sacola seja flutuante

<|end_of_query|>

Abaixo entre <RESPONSE> e </RESPONSE> está a resposta a ser avaliada:
<RESPONSE>


Prontinho! Criei um site de **delivery completo e funcional** em um único arquivo HTML, com a sacola flutuante contando os itens, painel de pedidos com formulário e tudo mais. É só salvar como `index.html` e abrir no navegador. 🚀

```html
<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>SaborExpress 🍽️ — Delivery</title>
<style>
  :root{
    --primary:#c1121f; --accent:#e63946;
    --bg:#f7f8fa; --card:#fff; --text:#1a1a1e; --muted:#8a94a3;
    --font:system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;
  }
  *{box-sizing:border-box;}
  body{margin:0;font-family:var(--font);background:var(--bg);color:var(--text);line-height:1.6;-webkit-font-smoothing:antialiased;}

  /* ---------------- Sacola flutuante ---------------- */
  .float-cart{
    position:fixed;bottom:20px;right:20px;z-index:1100;
    width:58px;height:58px;border-radius:50%;
    background:radial-gradient(circle at 30% 18%,#e63946 0%,#c1121f 100%);
    display:flex;align-items:center;justify-content:center;
    box-shadow:0 8px 24px rgba(230,57,7,.55),inset 0 -2px 0 rgba(255,255,255,.25);
    color:#fff;cursor:pointer;user-select:none;font-size:28px;
    outline:none;transition:transform .25s ease,box-shadow .25s,opacity .3s;
  }
  .float-cart:hover{transform:scale(1.08);box-shadow:0 12px 32px rgba(230,57,7,.65);}
  .float-cart:focus{box-shadow:0 0 0 4px #fff;outline:none;background:#a30e20;}
  .float-cart.cart-hidden{opacity:.5;pointer-events:none;}
  .float-cart .bc-count{
    position:absolute;top:-10px;right:-10px;min-width:26px;height:26px;
    border-radius:50%;background:#fff;color:var(--primary);font-size:15px;
    font-weight:800;display:flex;align-items:center;justify-content:center;
    box-shadow:0 2px 6px rgba(0,0,0,.25);
  }

  /* ---------------- Topbar ---------------- */
  .topbar{display:flex;align-items:center;justify-content:space-between;padding:12px 24px;
          background:#fff;position:relative;box-shadow:0 2px 10px rgba(0,0,0,.08);z-index:100;}
  .logo{font-size:1.35rem;font-weight:800;color:var(--primary);text-decoration:none;display:flex;align-items:center;gap:6px;}
  .topbar nav{display:flex;align-items:center;gap:4px;}
  .topbar a{color:var(--muted);text-decoration:none;font-weight:600;font-size:.9rem;padding:6px 12px;
             border-radius:8px;transition:.15s;white-space:nowrap;}
  .topbar a:hover{color:var(--accent);background:#f3f1ee;}
  .search{background:#f1f3f6;border:none;border-radius:28px;padding:9px 14px;font-size:.9rem;
          outline:none;color:#4a4e57;flex:1|max-width:240px;transition:.2s;}
  .search:focus{background:#fff;border:2px solid var(--accent);}

  /* ---------------- Hero ---------------- */
  .hero{background:linear-gradient(135deg,#c1121f 0%,#e63946 100%);color:#fff;text-align:center;
         padding:50px 20px 40px;scroll-margin-top:78px;}
  .hero .kick{letter-spacing:3px;font-size:.95rem;font-weight:700;opacity:.9;}
  .hero h1{font-size:2.5rem;margin:10px 0 10px;line-height:1.15;}
  .hero .sub{max-width:560px;margin:0 auto 22px;opacity:.95;font-size:1.03rem;}
  .cta-hero{display:inline-flex;align-items:center;gap:10px;background:#fff;color:var(--primary);
             font-weight:800;font-size:1rem;padding:14px 30px;border-radius:50px;
             box-shadow:0 8px 22px rgba(0,0,0,.32);cursor:pointer;
             transition:.2s;text-decoration:none;scroll-margin-top:80px;}
  .cta-hero:hover{transform:translateY(-2px);box-shadow:0 12px 30px rgba(0,0,0,.38);}
  .hero-glow::after{content:'';position:absolute;inset:-18px;border-radius:inherit;
                     background:radial-gradient(circle,rgba(230,57,7,.22) 0%,transparent 70%);pointer-events:none;}

  /* ---------------- Filtros ---------------- */
  .filters{display:flex;gap:7px;overflow-x:auto;padding:16px 0 8px;scrollbar-width:none;-webkit-overflow-scrolling:touch;}
  .filters::-webkit-scrollbar{display:none;}
  .filter-btn{flex:1;min-width:124px;background:#f3f5f8;border:none;border-radius:20px;
              padding:10px 14px;font-size:.85rem;font-weight:600;color:var(--muted);
              cursor:pointer;transition:.2s;white-space:nowrap;}
  .filter-btn.active{background:var(--accent);color:#fff;}

  /* ---------------- Produtos ---------------- */
  .sec{margin-bottom:30px;}
  .sec-title{display:flex;align-items:center;gap:10px;font-size:1.25rem;font-weight:800;margin-bottom:16px;}
  .sec-title .dot{width:9px;height:9px;border-radius:50%;background:var(--accent);}
  .grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:20px;}

  .card-wrap{display:flex;gap:14px;background:var(--card);border-radius:16px;overflow:hidden;
              box-shadow:0 2px 10px rgba(0,0,0,.06);cursor:pointer;
              transition:transform .25s ease,box-shadow .25s;user-select:none;}
  .card-wrap:hover{transform:translateY(-5px);box-shadow:0 14px 30px rgba(230,57,7,.13);}
  .card-wrap:focus-within{box-shadow:0 14px 30px rgba(230,57,7,.18);}
  .card-emoji{font-size:2.5rem;line-height:1;flex:none;max-width:64px;}
  .card-body{display:flex;flex-direction:column;flex:1;min-width:0;padding:16px 16px 18px;}
  .card-name{font-size:1.05rem;font-weight:700;color:#12161c;margin-bottom:4px;}
  .card-desc{font-size:.82rem;color:var(--muted);margin-bottom:10px;flex:1;line-height:1.5;}
  .card-footer{display:flex;align-items:center;justify-content:space-between;margin-top:6px;}
  .price{font-size:1.12rem;font-weight:800;color:var(--primary);}
  .tag{font-size:.7rem;background:var(--accent);color:#fff;padding:2px 8px;border-radius:10px;
        font-weight:700;}
  .add-btn{margin-top:14px;width:100%;padding:10px 14px;border:none;border-radius:12px;
            background:var(--primary);color:#fff;font-weight:700;font-size:.92rem;
            cursor:pointer;transition:.18s;}
  .add-btn:hover{background:#a30e20;transform:translateY(-1px);}
  .add-btn:active{transform:scale(.97);}

  /* ---------------- Painel da sacola ---------------- */
  .backdrop{position:fixed;inset:0;z-index:1101;background:rgba(0,0,0,.62);
             display:flex;align-items:flex-end;justify-content:center;opacity:0;pointer-events:none;
             transition:opacity .3s;}
  .backdrop.open{opacity:1;pointer-events:auto;}
  .panel{background:#fff;border-radius:26px;width:min(480px,92vw);max-height:92vh;
          overflow-y:auto;margin:auto auto 0;box-shadow:0 26px 72px rgba(0,0,0,.35);
          display:flex;flex-direction:column;padding:26px 24px 30px;}
  .ph{display:flex;align-items:center;justify-content:space-between;gap:10px;}
  .pi{display:flex;align-items:center;gap:10px;}
  .pi .ic{font-size:1.5rem;}
  .panel h2{font-size:1.3rem;font-weight:800;margin:2px 0 0;}
  .psub{color:var(--muted);font-size:.85rem;margin:0;}
  .pclose{background:none;border:none;font-size:1.5rem;cursor:pointer;color:#aeb4c0;
           transition:.15s;}
  .pclose:hover{color:var(--primary);}

  .clist{list-style:none;margin:0;padding:0;flex:1;overflow-y:auto;}
  .cl{display:flex;align-items:center;gap:14px;padding:13px 14px;
       border-bottom:1px solid #f3f5f8;border-left:3px solid #eef0f4;position:relative;}
  .cl:last-child{border-bottom:none;}
  .ci{flex:1;min-width:0;}
  .ci .nm{font-weight:600;font-size:.95rem;color:#12161c;margin-bottom:2px;}
  .ci .ds{font-size:.78rem;color:var(--muted);margin-bottom:6px;}
  .ci .pr{font-weight:700;color:var(--primary);font-size:.92rem;}
  .ctrl{display:flex;align-items:center;gap:6px;}
  .bq{width:30px;height:30px;border-radius:8px;border:1px solid #e6e9f0;background:#f3f5f8;
       font-size:1.15rem;font-weight:800;color:#5a6575;cursor:pointer;
       display:flex;align-items:center;justify-content:center;transition:.15s;}
  .bq:hover{background:var(--primary);color:#fff;}
  .br{border:1px solid #e2e6ec;border-radius:8px;padding:4px 9px;background:#fff;
       color:#888;font-weight:600;font-size:.82rem;cursor:pointer;transition:.15s;}
  .br:hover{background:#fceef0;border-color:var(--primary);color:var(--primary);}

  .pb{border-top:1px dashed #eaf0f5;padding-top:18px;}
  .tot{display:flex;justify-content:space-between;font-size:1.2rem;font-weight:800;margin-top:12px;}
  .note{font-size:.82rem;color:var(--muted);margin-top:10px;}
  .ch{margin-top:18px;}
  .r2{display:flex;gap:12px;margin-bottom:14px;}
  .fi{flex:1;padding:12px 14px;border:1px solid #dde1e8;border-radius:12px;
       font-size:.95rem;outline:none;background:#fff;transition:.15s;}
  .fi:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(230,57,7,.12);}
  .sb{flex:0 0 150px;padding:14px;background:var(--primary);color:#fff;border:none;
       border-radius:12px;font-size:1rem;font-weight:800;cursor:pointer;transition:.2s;}
  .sb:hover{background:#a30e20;}
  .sb.loading{opacity:.7;pointer-events:none;}

  /* Toast */
  .toast{position:fixed;bottom:26px;right:26px;z-index:1200;
          background:#1d1f23;color:#fff;padding:13px 18px;border-radius:12px;
          font-size:.9rem;line-height:1.5;max-width:340px;
          transform:translateY(22px)scale(.95);opacity:0;pointer-events:none;
          transition:.3s cubic-bezier(.4,0,.2,1);}
  .toast.on{transform:translateY(0)scale(1);opacity:1;pointer-events:auto;}

  footer{text-align:center;padding:40px 20px 60px;background:#16191f;color:#8b909e;
          font-size:.88rem;}
  @media(max-width:640px){
    .hero h1{font-size:1.9rem;}
    .topbar nav{display:none;}
    .topbar .search{max-width:100%;}
    .panel{margin:0;border-radius:22px;}
    .send-btn{flex:0 0 130px;}
    .grid{grid-template-columns:1fr;}
  }
</style>
</head>
<body>

<!-- Sacola flutuante -->
<button class="float-cart" type="button" aria-label="Abrir sacola" role="button">
  <svg viewBox="0 0 24 24" fill="currentColor" class="bag-svg" aria-hidden="true" width="34" height="34">
    <path d="M6 2h12v6c0 5-3 7-3 11H9V8c0-2 1-4 3-6z"/>
    <path d="M18 9h-6c-1 0-2 1-2 2v1c0-5 3-7 3-7h6c0 0 3 2 3 7v-1c0-1-1-2-2-2z"/>
  </svg>
  <span class="bc-count" id="bc-count" aria-live="polite">0</span>
</button>

<header class="topbar">
  <a href="#" class="logo">🔥 Sabor<span>Express</span></a>
  <nav>
    <a href="#hamburgueres">Hambúrgueres</a>
    <a href="#pizzas">Pizza</a>
    <a href="#esfihas">Esfihas</a>
    <a href="#massas">Massas</a>
    <a href="#japones">Japonês</a>
    <a href="#petiscos">Petiscos</a>
    <a href="#doces-bebidas">Bebidas</a>
  </nav>
  <input type="search" class="search" placeholder="Buscar por nome..." aria-label="Buscar">
</header>

<section class="hero">
  <div>
    <div class="kick">🍽️ Delivery artesanal</div>
    <h1>Comida quente,<br>chegando quentinha aí.</h1>
    <p class="sub">Hambúrgueres artesanais, pizzas, pratos japoneses, petiscos e sobremesas — feitos na hora e entregues em até 40 minutos.</p>
    <button class="cta-hero" onclick="setFilter('burgers')">Ver Hambúrgueres e pedir agora</button>
  </div>
  <div class="hero-glow"></div>
</section>

<div class="filters" id="filters" role="tablist" aria-label="Filtrar categorias">
  <button class="filter-btn active" data-cat="todos" onclick="setFilter('todos')">Todas</button>
  <button class="filter-btn" data-cat="burgers">Hambúrgueres</button>
  <button class="filter-btn" data-cat="pizza">Pizza</button>
  <button class="filter-btn" data-cat="esfiha">Esfihas</button>
  <button class="filter-btn" data-cat="massas">Massas</button>
  <button class="filter-btn" data-cat="sushi">Japonês</button>
  <button class="filter-btn" data-cat="petiscos">Petiscos</button>
  <button class="filter-btn" data-cat="doces-bebidas">Bebidas</button>
</div>

<main id="products"></main>

<div class="backdrop" id="backdrop" role="dialog" aria-labelledby="cart-title" aria-hidden="false">
  <div class="panel" id="panel">
    <div class="ph">
      <div class="pi"><span class="ic">🛍</span>
        <h2 id="cart-title">Sua sacola</h2>
        <p class="psub" id="cart-sub">0 itens · R$ 0,00</p></div>
      <button class="pclose" aria-label="Fechar sacola" onclick="closeCart()"></button>
    </div>

    <ul class="clist" id="cart-list"></ul>

    <div class="pb">
      <div class="tot"><span>Total do pedido</span><span id="order-total">R$ 0,00</span></div>
      <p class="note">Entrega grátis acima de R$ 60 · Pagamento seguro (cartão ou Pix)</p>

      <form class="ch" id="checkout" novalidate onsubmit="processOrder(event)">
        <div class="r2">
          <input class="fi" id="inp-nome" placeholder="Seu nome completo *" required autocomplete="name">
          <input class="fi" id="inp-tel" placeholder="Celular (opcional)" autocomplete="tel">
        </div>
        <div class="r2">
          <input class="fi" id="inp-rua" placeholder="Endereço, número *" required autocomplete="street-address">
          <input class="fi" id="inp-local" placeholder="Bairro, cidade e CEP *" required autocomplete="address-level1">
        </div>
        <button type="submit" class="sb" id="btn-order">Finalizar pedido 🚀</button>
      </form>
    </div>
  </div>
</div>

<footer>
  <div>
    <strong>SaborExpress</strong> · Delivery desde 2024<br>
    Hambúrgueres, pizzas e pratos preparados na hora • Entrega em até 40 min<br>
    © 2025 SaborExpress. Todos os direitos reservados.
  </div>
</footer>

<script>
// ============================ DADOS ============================
const PRODUCTS = [
  { id:'smash',   cat:'burgers', name:'X-Tudo Smash',      desc:'Pão australiano grelhado com duas carnes angus, cheddar cremoso e bacon crocante.',           price:32.90, emoji:'🍔' },
  { id:'bacon',   cat:'burgers', name:'Bacon Cheeseburger',desc:'O clássico com muito cheddar e uma camada extra de bacon suculento.',                      price:27.50, emoji:'🍔' },
  { id:'duplo',   cat:'burgers', name:'Duplo Cheddar',     desc:'Duas carnes, cheddar duplo, alface, tomate e pão artesanal fermentado.',                                        price:38.90, emoji:'🍔' },
  { id:'frango',  cat:'burgers', name:'Frango Crocante',   desc:'Peito de frango empanado estilo katsu, maionese especial e arroz japonês.',                                     price:28.50, emoji:'🍗' },
  { id:'pastel',  cat:'esfiha',   name:'Pastel de Belém',  desc:'Croquete recheado com queijo e frango, servido com molho tartar.',                                             price:24.90, emoji:'🥟' },
  { id:'esfiha1', cat:'esfiha',   name:'Esfiha de Carne',  desc:'Massa folhada crocante com recheio de carne moída temperada.',                                                 price:12.90, emoji:'🥟' },
  { id:'esfiha2', cat:'esfiha',   name:'Esfiha de Queijo', desc:'Massa fina e dourada com mussarela derretendo na boca.',                                           price:13.90, emoji:'🥟' },
  { id:'calab',   cat:'pizza',    name:'Calabresa GG',     desc:'Mussarela, calabresa fatiada, mussarela extra e borda estufada.',                                              price:47.90, emoji:'🍕' },
  { id:'marg',    cat:'pizza',    name:'Margherita',       desc:'Molho de tomate fresco, mussarela, manjericão e azeite extravirgem.',                                          price:42.50, emoji:'🍕' },
  { id:'nhoque',  cat:'massas',   name:'Nhoque à Bolonhesa',desc:'Nhoques caseiros cobertos com ragu de carne bolonhesa.',                                 price:39.90, emoji:'🍝' },
  { id:'sushi',   cat:'sushi',    name:'Sushi Especial',   desc:'Uraken de salmão com cream cheese e pepino (ou temaki de camarão).',                                           price:54.90, emoji:'🍣' },
  { id:'temaki',  cat:'sushi',    name:'Temaki de Camarão',desc:'Cones crocantes com camarão, cream cheese e cebolinha.',                                    price:42.00, emoji:'🍣' },
  { id:'coxinha', cat:'petiscos', name:'Coxinha Gigante',  desc:'Empanada dupla crocante, muito recheio e na medida certa.',                                  price:19.90, emoji:'🧡' },
  { id:'picole',  cat:'petiscos', name:'Picolé de Creme',  desc:'Picolés nos sabores baunilha, morango e ninho — perfeitos para o verão.',                   price: 9.90,  emoji:'🍧' },
  { id:'pq',      cat:'doces',    name:'Pão de Queijo Duplo',desc:'Dois pãezinhos quentíssimos saindo direto do forno.',                                    price:21.00, emoji:'🥖' },
  { id:'gelad',   cat:'doces',    name:'Geladinho Ube',    desc:'Sobremesa refrescante nos sabores ube, morango e coco.',                                                        price: 8.90,  emoji:'🍦' },
  { id:'cola',    cat:'bebidas',  name:'Refrante Cola 2L', desc:'Cola gelada com gelo grande para qualquer hora do dia.',                                         price:14.90, emoji:'🥤' },
  { id:'suco',    cat:'bebidas',  name:'Suco Natural 1L',  desc:'Laranja, abacaxi ou uva batidos na hora, sem açúcar adicionado.',                              price:11.90, emoji:'🍋' },
];

const CATEGORIES = [
  ['all','Todos'], ['burgers','Hambúrgueres'], ['pizza','Pizza'], ['esfiha','Esfihas'],
  ['massas','Massas'], ['sushi','Japonês'], ['petiscos','Petiscos'], ['doces','Doces & Bebidas']
];

const SECIDS = { all:'produtos', burgers:'hamburgueres', pizza:'pizzas', esfiha:'esfihas',
                massas:'massas', sushi:'japones', petiscos:'petiscos', doces:'doces-bebidas' };

// ============================ ESTADO ============================
let selectedCat = 'todos';
let cart = JSON.parse(localStorage.getItem('saborexpress_cart')) || [];
let isOpen = false, hideFloat = false, refEl = null;

function saveCart(){ localStorage.setItem('saborexpress_cart', JSON.stringify(cart)); }

const ESC = new Map([['&','&'],['<','&lt;'],['>','&gt;'],['"','"'],["'","'"]]);
function esc(s){
  if(typeof s !== 'string') return '';
  let out = '';
  for(let i=0;i<s.length;i++){ if(ESC.has(s[i])) out += ESC.get(s[i]); else out += s[i]; }
  return out;
}
const FMT = v => Number(v).toFixed(2).replace('.',',');

function qtySum(){ return cart.reduce((a,i)=>a+(i.qty||0),0); }
function calcTotal(){ return cart.reduce((a,i)=>a+(i.price||0)*(i.qty||1),0); }

function updateBadge(){
  const el = document.getElementById('bc-count'); if(!el) return;
  const n = qtySum();
  el.textContent = n;
  el.style.display = n > 0 ? 'block' : 'none';
  const p = el.parentElement;
  p.style.opacity = n === 0 ? '.5' : '1';
  p.style.transform = n > 0 ? 'scale(1)' : '';
}

function addToCart(id){
  const p = PRODUCTS.find(x => x.id === id);
  if(!p) return;
  const idx = cart.findIndex(x => x.id === id);
  if(idx >= 0) cart[idx].qty++;
  else cart.push({ id:p.id, name:p.name, price:p.price, emoji:p.emoji, qty:1 });
  saveCart(); updateBadge();
  showToast(`+ ${p.name} na sacola`);
  const btn = document.querySelector(`[data-id="${id}"]`);
  if(btn){
    btn.style.transition='none'; btn.style.transform='scale(1.12)'; btn.style.borderColor='#ffd44e';
    setTimeout(()=>{
      btn.style.transition='transform .18s ease';
      btn.style.transform='scale(1)'; btn.style.borderColor='#ccd4df';
    },320);
  }
}

function removeFromCart(id){
  const idx = cart.findIndex(x => x.id === id);
  if(idx < 0) return;
  cart.splice(idx,1);
  saveCart(); updateBadge();
  showToast('Item removido da sacola');
}

function changeQty(id, delta){
  const p = PRODUCTS.find(x => x.id === id);
  if(!p) return;
  const idx = cart.findIndex(x => x.id === id);
  if(idx < 0){
    cart.push({ id:p.id, name:p.name, price:p.price, emoji:p.emoji, qty: Math.max(1, delta) });
  } else {
    cart[idx].qty = Math.max(1, (cart[idx].qty) + delta);
  }
  saveCart(); updateBadge();
}

// ============================ RENDERIZAÇÃO ============================
function cheapestIn(cat){
  const arr = PRODUCTS.filter(p => p.cat === cat);
  if(arr.length === 0) return null;
  const min = Math.min(...arr.map(p=>p.price));
  return arr.filter(p => Math.abs(p.price - min) < 0.01)[0];
}

function renderCards(cat){
  const container = document.getElementById('products');
  if(!container) return;

  let html = '';
  CATEGORIES.forEach(([c, title]) => {
    if(c === 'all' && cat !== 'all') return;
    if(!SECIDS[c]) return;
    const plist = PRODUCTS.filter(p => cat === 'all' || p.cat === c);
    if(plist.length === 0 && c !== 'all') return;

    const id = SECIDS[c];
    const min = Math.min(...plist.map(p => p.price));

    const cards = plist.map(p => {
      const isLeast = Math.abs(p.price - min) < 0.01;
      return `<article class="card-wrap" tabindex="0" data-id="${p.id}" id="${id}-${plist.indexOf(p)}">
        <div class="card-emoji">${p.emoji}</div>
        <div class="card-body">
          <h3 class="card-name">${p.name}</h3>
          <p class="card-desc">${esc(p.desc)}</p>
          <div class="card-footer">
            <span class="price">${FMT(p.price)}</span>
            ${isLeast ? '<span class="tag">Mais barato</span>' : ''}
          </div>
          <button class="add-btn" data-id="${p.id}" aria-label="Adicionar ${p.name} à sacola"
                    onclick="addToCart('${p.id}')">Adicionar à sacola</button>
        </div>
      </article>`;
    }).join('');

    html += `<section class="sec" id="${id}"><h2 class="sec-title"><span class="dot"></span>${title}</h2>${cards}</section>\n`;
  });
  container.innerHTML = html;
  updateFilterButtons(cat);
}

function updateFilterButtons(cat){
  const fb = document.getElementById('filters');
  if(!fb) return;
  [...fb.children].forEach(btn => btn.classList.toggle('active', btn.dataset.cat === cat));
}

