function openCart(){
  if(isOpen || !document.getElementById('panel')) return;
  isOpen = true;
  const bd = document.getElementById('backdrop');
  const pl = document.getElementById('panel');
  hideFloat = true;
  document.querySelector('.float-cart').classList.add('cart-hidden');
  bd.classList.add('open');
