function recalcTotals(){
  const total = calcTotal();
  document.getElementById('order-total').textContent = 'R$ ' + FMT(total);
  const n = qtySum();
  document.getElementById('cart-sub').textContent = n > 0 ?
    `${n} item${n!==1?'s':''} · R$ ${FMT(total)}` : '0 itens · R$ 0,00';
}

function focusInPanel(){
  const first = document.getElementById('ctl-0');
  if(!first) return;
  if(document.activeElement !== first) first.focus();
  if(document.getElementById('panel') && document.activeElement !== document.getElementById('panel'))
    document.getElementById('panel').focus();
}

let gHandler = null;
function addGlobalKeys(){
  gHandler = (e) => {
    if(e.key === 'Escape'){ closeCart(); return; }
    if(!isOpen) return;
    if(e.key === 'Tab'){
      e.preventDefault();
      const f = document.getElementById('ctl-0');
      const l = document.getElementById('ctl-' + (cart.length-1));
      const cur = document.activeElement;
      const next = cur && cur.tagName && (cur.nextElementSibling != null || cur === l);
      const prev = cur && cur.tagName && (cur.previousElementSibling != null || cur === f);
      if(!next) moveFocus('next');
      else if(!prev) moveFocus('prev');
    }
  };
  document.addEventListener('keydown', gHandler);
}
function removeGlobalKeys(){ if(gHandler) document.removeEventListener('keydown', gHandler); }

function moveFocus(dir){
  const f = document.getElementById('ctl-0');
  const l = document.getElementById('ctl-' + (cart.length-1));
  const cur = document.activeElement && cur?.tagName;
  if(!cur) return;
  if(dir === 'next'){
    if(!cur || cur === l) return;
    if(cur.nextElementSibling) moveFocus('next'); // evita loop infinito
    return;
  }
  if(dir === 'prev'){
    if(!cur || cur === f) return;
    if(cur.previousElementSibling) moveFocus('prev');
    return;
  }
  const nxt = dir === 'next' ? cur.nextElementSibling : cur.previousElementSibling;
  if(nxt) nxt.focus();
}

